// =====================================================================
// Aviso a Slack cuando una conversacion se escala a una persona.
//
// Cuelga detras de "Hay que asignar?", asi que dispara UNA SOLA VEZ por
// conversacion: en el turno exacto en que se pone la etiqueta
// 'necesita-humano'. Los mensajes siguientes del cliente NO vuelven a
// avisar -- ademas 'Filtrar necesita-humano', arriba de todo, ya los corta
// antes de que entren al flujo.
// =====================================================================
const cfg = $('Config').first().json;
const s = $('Armar salida').first().json;

// =====================================================================
// POR QUE EL CRUCE SE HACE ACA Y NO EN EL FILTRO DE NOTION
//
// En Notion los telefonos NO estan normalizados: la misma persona puede
// cargar +5492345890912, +54 9 2345 890912 o +549234589-0912. El filtro
// 'contains' de Notion busca sobre el TEXTO CRUDO, asi que:
//
//   guardado : +549234589-0912
//   digitos  : 5492345890912  -> ultimos 8: 45890912
//   crudo    : ...4589-0912   -> NO contiene '45890912' (el guion lo parte)
//
// Resultado: 0 filas, y el aviso saldria diciendo "sin card" para un
// cliente que SI esta cargado. Ningun substring salva esto -- seria
// adivinar como tipeo el numero quien lo cargo.
//
// Por eso Notion devuelve todas las cards con telefono y el cruce se hace
// aca, sobre SOLO DIGITOS, que es lo unico que aguanta cualquier formato.
// El precio es paginar la base en cada escalada; son pocas por dia.
//
// Si algun dia la base se hace grande, la solucion de fondo es una
// propiedad ya normalizada en Notion, no un filtro mas ingenioso.
// =====================================================================
const soloDigitos = (v) => String(v == null ? '' : v).replace(/\D/g, '');

// Se comparan los ultimos 8 digitos: alcanza para identificar sin depender
// del codigo de pais ni del 9 que Argentina mete despues del 54. Menos de
// 8 daria falsos positivos, asi que si el numero es mas corto no se cruza
// con nada y el aviso sale igual, avisando que no encontro card.
const target8 = soloDigitos(s.telefono).slice(-8);

// El nodo de Notion tiene alwaysOutputData prendido. Sin eso, cuando no
// encuentra ninguna card devuelve 0 items y n8n saltea todo lo de abajo:
// Slack no avisaria nunca. Y ese es justo el caso MAS importante -- un
// numero que no esta en el CRM pidiendo hablar con alguien.
// El precio es que puede llegar un item vacio {}, que se descarta aca.
const pages = target8.length < 8 ? [] : $input.all()
  .map((i) => i.json)
  .filter((p) => {
    if (!p || !p.id || !p.url) return false;
    return soloDigitos(p.property_whatsapp_kdm).slice(-8) === target8;
  });

let bloqueCard;
if (pages.length === 0) {
  bloqueCard = ':warning: Sin card en Notion para este numero';
} else {
  bloqueCard = pages.slice(0, 3).map((p) => {
    const nombreCard = p.property_nombre_oportunidad || p.name || 'Card sin nombre';
    const status = p.property_status ? ' | ' + p.property_status : '';
    // Owner viene como array de mails. Se muestra solo el nombre de pila:
    // 'damian.deggeller@xtract.app' -> 'Damian'.
    const ownerEmail = Array.isArray(p.property_owner) ? p.property_owner[0] : p.property_owner;
    let owner = '';
    if (ownerEmail) {
      const pila = String(ownerEmail).split('@')[0].split('.')[0];
      owner = ' | Owner: ' + pila.charAt(0).toUpperCase() + pila.slice(1);
    }
    return ':link: <' + p.url + '|' + nombreCard + '>' + status + owner;
  }).join('\n');
  if (pages.length > 3) {
    bloqueCard += '\n_(+' + (pages.length - 3) + ' cards mas con este numero)_';
  }
}

// =====================================================================
// LA MENCION TIENE QUE SER <@ID>, NO EL NOMBRE
//
// Escribir "Damian Deggeller" en el texto queda lindo y NO LE NOTIFICA A
// NADIE: es texto plano. Slack solo notifica con la sintaxis <@U09PYEWUHGF>,
// donde ese id es el member id de SLACK -- no el de Chatwoot, que es de
// otro sistema y no sirve para esto.
//
// El fallback al nombre existe para que, si algun dia falta el id en
// Config, el canal reciba "Damian Deggeller" en vez de un "<@>" roto.
// =====================================================================
const quienAtiende = s.asignado_slack
  ? '<@' + s.asignado_slack + '>'
  : (s.asignado_a || 'nadie');

// El mensaje del cliente va citado, para que se lea de un vistazo por que
// se escalo sin tener que abrir Chatwoot.
const cita = String(s.input || '(sin texto)').split('\n').map((l) => '> ' + l).join('\n');

const linkCw = cfg.CHATWOOT_URL + '/app/accounts/' + cfg.CHATWOOT_ACCOUNT_ID +
  '/conversations/' + s.conversation_id;

const quien = s.empresa ? s.nombre + ' - ' + s.empresa : s.nombre;

const texto = [
  '<!here> :raising_hand: Un cliente pide hablar con una persona',
  '*' + quien + '*  +' + soloDigitos(s.telefono),
  ':bust_in_silhouette: Le toca a ' + quienAtiende,
  '',
  cita,
  '',
  bloqueCard,
  ':speech_balloon: <' + linkCw + '|Responder en Chatwoot>'
].join('\n');

return [{ json: { texto_slack: texto, cards_encontradas: pages.length } }];
